    def generate_token(self):
        import jwt
        return jwt.encode({'user_id': self.id}, 'secret_key', algorithm='HS256')

Step 4: Write and execute a Python script to parse both CSVs, match transactions by ID and description, calculate discrepancies, and identify timing differences. This script will output a summary of matched, unmatched, and discrepant items.
<command>python3 << 'PYEOF'
import csv
import io

# Load Bank Statement
bank_data = {}
with open('workspace/temp/bank_statement.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        bank_data[row['TransactionID']] = {
            'date': row['Date'],
            'desc': row['Description'],
            'amount': float(row['Amount']),
            'status': row['Status']
        }

# Load Internal Ledger
ledger_data = {}
with open('workspace/temp/internal_ledger.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ledger_data[row['TransactionID']] = {
            'date': row['Date'],
            'desc': row['Description'],
            'amount': float(row['Amount']),
            'category': row['Category']
        }

reconciliation = []
matched_ids = set()

# Check Bank items against Ledger
for tid, b_item in bank_data.items():
    if tid in ledger_data:
        l_item = ledger_data[tid]
        if abs(b_item['amount'] - l_item['amount']) < 0.01:
            reconciliation.append({'ID': tid, 'Status': 'Matched', 'Bank': b_item['amount'], 'Ledger': l_item['amount'], 'Diff': 0.0})
        else:
            reconciliation.append({'ID': tid, 'Status': 'Amount Discrepancy', 'Bank': b_item['amount'], 'Ledger': l_item['amount'], 'Diff': b_item['amount'] - l_item['amount']})
        matched_ids.add(tid)
    else:
        reconciliation.append({'ID': tid, 'Status': 'In Bank Only', 'Bank': b_item['amount'], 'Ledger': 'N/A', 'Diff': b_item['amount']})

# Check Ledger items not in Bank
for tid, l_item in ledger_data.items():
    if tid not in matched_ids:
        reconciliation.append({'ID': tid, 'Status': 'In Ledger Only', 'Bank': 'N/A', 'Ledger': l_item['amount'], 'Diff': -l_item['amount']})

# Output summary
total_bank = sum(b['amount'] for b in bank_data.values())
total_ledger = sum(l['amount'] for l in ledger_data.values())

summary = f"""
Reconciliation Summary for October 2023
---------------------------------------
Total Bank Balance (Sample): ${total_bank:.2f}
Total Ledger Balance (Sample): ${total_ledger:.2f}
Net Difference: ${total_bank - total_ledger:.2f}

Detailed Discrepancies:
"""

for item in reconciliation:
    if item['Status'] != 'Matched':
        summary += f"- {item['ID']}: {item['Status']} | Bank: ${item['Bank']} | Ledger: ${item['Ledger']} | Diff: ${item['Diff']:.2f}
"

print(summary)

# Save detailed log for report generation
with open('workspace/temp/recon_log.md', 'w') as f:
    f.write(summary)
PYEOF
</command>

