  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'postgres',
  password: process.env.DB_PASS || 'secret',
  database: process.env.DB_NAME || 'mydb'
});

const redisClient = redis.createClient({ url: `redis://${process.env.REDIS_HOST || 'localhost'}:6379` });

app.get('/', async (req, res) => {
  try {
    const client = await pool.connect();
    const result = await client.query('SELECT NOW() as time');
    client.release();

    let cacheHit = false;
    try {
      await redisClient.connect();
      const cached = await redisClient.get('latest_time');
      if (cached) {
        cacheHit = true;
        res.json({ message: 'Cache Hit', time: cached });
        return;
      }
      await redisClient.set('latest_time', result.rows[0].time, { EX: 60 });
    } catch (redisErr) {
      console.warn('Redis unavailable:', redisErr.message);
    }

    res.json({ message: 'Database Hit', time: result.rows[0].time });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Database connection failed' });
  }
});

app.listen(port, () => {
