import yaml
import os
import re

# Load the raw YAML
with open('workspace/temp/raw_config.yaml', 'r') as f:
    config = yaml.safe_load(f)

def resolve_env_vars(value):
    if isinstance(value, str):
        env_pattern = re.compile(r'\$\{([^}]+)\}')
        def replace_env(match):
            var_name = match.group(1)
            return os.environ.get(var_name, f'PLACEHOLDER_{var_name}')
        return env_pattern.sub(replace_env, value)
    return value

def transform_value(key, value):
    # Convert string numbers to integers for specific keys
    if key in ['port', 'max_connections', 'retry_attempts', 'database', 'version']:
        if isinstance(value, str):
            try:
                return int(value)
            except ValueError:
                return value
    # Resolve environment variables
    if isinstance(value, str):
        return resolve_env_vars(value)
    return value

# Traverse and transform the config
def transform_dict(d, parent_key=''):
    new_d = {}
    for k, v in d.items():
        if isinstance(v, dict):
            new_d[k] = transform_dict(v, parent_key=k)
        elif isinstance(v, list):
            new_d[k] = [transform_dict(item, parent_key=k) if isinstance(item, dict) else transform_value(k, item) for item in v]
        else:
            new_d[k] = transform_value(k, v)
    return new_d

transformed_config = transform_dict(config)

# Save transformed config
with open('workspace/temp/transformed_config.yaml', 'w') as f:
    yaml.dump(transformed_config, f, default_flow_style=False)

print('Transformation complete.')
print(yaml.dump(transformed_config, default_flow_style=False))
