"""
Core data processing engine.
Handles ingestion, validation, and transformation of data streams.
"""
from pydantic import BaseModel
import requests

class DataConfig(BaseModel):
    source_url: str
    chunk_size: int = 1024

class DataEngine:
    def __init__(self):
        self.running = False
        self.config = None

    def start(self, config: DataConfig):
        self.config = config
        self.running = True
        self._fetch_data()

    def _fetch_data(self):
        # Simulated fetch logic
        response = requests.get(self.config.source_url)
        return response.json()

    def is_ready(self):
        return self.running

import unittest
from src.core.engine import DataEngine, DataConfig

class TestEngine(unittest.TestCase):
    def test_engine_start(self):
        config = DataConfig(source_url="http://example.com/data")
        engine = DataEngine()
        engine.start(config)
        self.assertTrue(engine.is_ready())

    def test_invalid_config(self):
        with self.assertRaises(Exception):
            DataConfig(source_url="invalid-url")

if __name__ == '__main__':
    unittest.main()

